 as x(slug text,component_title text,position int,quantity numeric,unit text,quantity_text text,display_name text,original_text text,scaling text,is_optional boolean)
)
insert into public.recipe_ingredients(recipe_id,component_id,position,quantity,unit,quantity_text,display_name,original_text,scaling,is_optional)
select r.id,c.id,d.position,d.quantity,d.unit,d.quantity_text,d.display_name,d.original_text,d.scaling,d.is_optional
from d join public.recipes r on r.slug=d.slug
join public.recipe_components c on c.recipe_id=r.id and c.title=d.component_title
where not exists(select 1 from public.recipe_ingredients i where i.recipe_id=r.id and i.component_id=c.id and i.position=d.position);

