:"Leve ao fogo médio, mexendo sempre até cozinhar e engrossar.","original_text":"Leve ao fogo médio, mexendo sempre até cozinhar e engrossar.","component_title":"Manjar Ouro Branco"},{"slug":"manjar-ouro-branco","position":3,"instruction":"Retire do fogo, acrescente o creme de leite e misture bem.","original_text":"Retire do fogo, acrescente o creme de leite e misture bem.","component_title":"Manjar Ouro Branco"},{"slug":"manjar-ouro-branco","position":4,"instruction":"Adicione os bombons picados e misture novamente.","original_text":"Adicione os bombons picados e misture novamente.","component_title":"Manjar Ouro Branco"},{"slug":"manjar-ouro-branco","position":5,"instruction":"Coloque em uma fôrma de buraco no meio de 30cm de diâmetro decorada e leve à geladeira por 4 horas.","original_text":"Coloque em uma fôrma de buraco no meio de 30cm de diâmetro decorada e leve à geladeira por 4 horas.","component_title":"Manjar Ouro Branco"},{"slug":"manjar-ouro-branco","position":1,"instruction":"Desenforme em um prato de servir, regue com a calda, decore com bombons e sirva.","original_text":"Desenforme em um prato de servir, regue com a calda, decore com bombons e sirva.","component_title":"Decoração e finalização"}]$data$::jsonb)
 as x(slug text,component_title text,position int,instruction text,original_text text)
)
insert into public.recipe_steps(recipe_id,component_id,position,instruction,original_text)
select r.id,c.id,d.position,d.instruction,d.original_text
from d join public.recipes r on r.slug=d.slug
join public.recipe_components c on c.recipe_id=r.id and c.title=d.component_title
where not exists(select 1 from public.recipe_steps s where s.recipe_id=r.id and s.component_id=c.id and s.position=d.position);
commit;